class Solution {
  public int firstArrivalsPositiveInkInvoice(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>seen=new HashSet<>();for(int x:a)if(seen.add(x))out.add(x);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
